import { useEffect, useState } from "react";
import axios from "axios";
import { useAuth } from "../context/AuthContext";

export default function AdminDashboard() {
  const [units, setUnits] = useState([]);
  const [form, setForm] = useState({
    name: "",
    size: "",
    pricePerDay: ""
  });

  //const userInfo = JSON.parse(localStorage.getItem("userInfo"));
  //const token = userInfo?.token;
  
  const { user } = useAuth();
  const token = user?.token;
  const [showModal, setShowModal] = useState(false);

  <button
  style={{
    background: "#2563EB",
    color: "white",
    padding: "10px 15px",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    marginBottom: "20px"
  }}
  onClick={() => setShowModal(true)}
>
  + Create Unit
</button>

  //  Fetch all units
  const fetchUnits = async () => {
    try {
      const { data } = await axios.get("http://localhost:5001/api/units");
      setUnits(data);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchUnits();
  }, []);

  //  Create new unit
  const handleCreate = async (e) => {
    setShowModal(false);
    e.preventDefault();

    try {
      await axios.post(
        "http://localhost:5001/api/units",
        form,
        {
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );

      alert(" Unit created");

      setForm({ name: "", size: "", pricePerDay: "" });
      fetchUnits();

    } catch (error) {
      alert(error.response?.data?.message || "Error creating unit");
    }
  };

  //  Delete unit (ADMIN FEATURE)
  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this unit?")) return;

    try {
      await axios.delete(
        `http://localhost:5001/api/units/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );

      alert(" Unit deleted");

      setUnits(units.filter(u => u._id !== id));

    } catch (error) {
      alert(error.response?.data?.message || "Delete failed");
    }
  };

  return (
    <div style={{ padding: "30px", background: "#F3F4F6", minHeight: "100vh" }}>
      <h2>Admin Dashboard</h2>

      {/* ✅ CREATE UNIT FORM */}
      <h3>Create New Storage Unit</h3>

      <form onSubmit={handleCreate}>
        <input
          type="text"
          placeholder="Name"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
          required
        />

        <input
          type="text"
          placeholder="Size (Small/Medium/Large)"
          value={form.size}
          onChange={(e) => setForm({ ...form, size: e.target.value })}
          required
        />

        <input
          type="number"
          placeholder="Price per Day"
          value={form.pricePerDay}
          onChange={(e) =>
            setForm({ ...form, pricePerDay: e.target.value })
          }
          required
        />

        <button type="submit">Create Unit</button>
      </form>

      {/*  LIST UNITS */}
      <h3>All Storage Units</h3>

      {units.length === 0 && <p>No units found.</p>}

      {units.map((unit) => (
<div
  key={unit._id}
  style={{
    background: "white",
    padding: "20px",
    borderRadius: "10px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
    marginBottom: "15px"
  }}
>
  <h3>{unit.name}</h3>
  <p><strong>Size:</strong> {unit.size}</p>
  <p><strong>Price:</strong> ${unit.pricePerDay}</p>
  <p>{unit.available ? "✅ Available" : "❌ Booked"}</p>

  <button
    style={{
      marginTop: "10px",
      background: "#EF4444",
      color: "white",
      padding: "8px",
      border: "none",
      borderRadius: "5px"
    }}
    onClick={() => handleDelete(unit._id)}
  >
    Delete
  </button>
</div>
      ))}
      {showModal && (
  <div style={overlay}>
    <div style={modal}>
      <h3>Create New Storage Unit</h3>

      <input
        type="text"
        placeholder="Unit Name"
        value={form.name}
        onChange={(e) => setForm({ ...form, name: e.target.value })}
        style={input}
      />

      <input
        type="text"
        placeholder="Size (Small / Medium / Large)"
        value={form.size}
        onChange={(e) => setForm({ ...form, size: e.target.value })}
        style={input}
      />

      <input
        type="number"
        placeholder="Price per day"
        value={form.pricePerDay}
        onChange={(e) =>
          setForm({ ...form, pricePerDay: e.target.value })
        }
        style={input}
      />

      <button style={primaryBtn} onClick={handleCreate}>
        Create Unit
      </button>

      <button
        style={cancelBtn}
        onClick={() => setShowModal(false)}
      >
        Cancel
      </button>
    </div>
  </div>
)}

    </div>
  );
}
const overlay = {
  position: "fixed",
  top: 0,
  left: 0,
  width: "100%",
  height: "100%",
  background: "rgba(0,0,0,0.5)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center"
};

const modal = {
  background: "white",
  padding: "25px",
  borderRadius: "10px",
  width: "300px",
  display: "flex",
  flexDirection: "column",
  gap: "10px"
};

const input = {
  padding: "8px",
  borderRadius: "5px",
  border: "1px solid #ddd"
};

const primaryBtn = {
  background: "#2563EB",
  color: "white",
  padding: "10px",
  border: "none",
  borderRadius: "5px"
};

const cancelBtn = {
  marginTop: "5px",
  padding: "8px",
  border: "none",
  background: "#ddd",
  borderRadius: "5px"
};
